#!/bin/bash
# Prepare all data for this environment.
#
# Estimated total download size: 0 GB (no external downloads)
# Estimated disk usage: ~20 MB (all committed scene files)
#
# The benchmark is procedural: the public training scenes are generated by
# data/scenes.py from fixed public seeds (idempotent: existing files are kept).
# The test-scene inputs in data/test/ are committed to git (their answers are
# held by the evaluator), so nothing has to be fetched.
set -e
cd /home/user
python data/scenes.py --out-root data/train
ls data/test/synthetic_validation_paper/*.json data/test/synthetic_large_motion/*.json > /dev/null
